 60→  alt: string;
 61→}
 62→
 63→export function ImageGallery({ images, alt }: ImageGalleryProps) {
 64→  if (images.length === 0) return null;
 65→
 66→  const rows = buildLayout(images);
 67→
 68→  return (
 69→    <div className={styles.gallery}>
 70→      {rows.map((row, ri) => {
 71→        if (row.type === "full") {
 72→          return (
 73→            <div key={ri} className={styles.rowFull}>
 74→              <Image
 75→                src={row.images[0]}
 76→                alt={`${alt} detail`}
 77→                width={2400}
 78→                height={1600}
 79→                style={{ width: "100%", height: "auto", borderRadius: "var(--img-radius)" }}
 80→                sizes="(max-width: 768px) 100vw, (max-width: 1400px) 90vw, 1400px"
 81→              />
 82→            </div>
 83→          );
 84→        }
 85→
 86→        return (
 87→          <div
 88→            key={ri}
 89→            className={styles.rowPair}
 90→            style={{
 91→              gridTemplateColumns: row.type === "wide-narrow" ? "2fr 1fr" : "1fr 2fr",
 92→            }}
 93→          >
 94→            {row.images.map((src, ii) => (
 95→              <Image
 96→                key={ii}
 97→                src={src}
 98→                alt={`${alt} detail`}
 99→                width={2400}
100→                height={1600}
101→                style={{ width: "100%", height: "auto", borderRadius: "var(--img-radius)" }}
102→                sizes={row.type === "wide-narrow"
103→                  ? (ii === 0 ? "(max-width: 768px) 100vw, 60vw" : "(max-width: 768px) 100vw, 30vw")
104→                  : (ii === 0 ? "(max-width: 768px) 100vw, 30vw" : "(max-width: 768px) 100vw, 60vw")
105→                }
106→              />
107→            ))}
108→          </div>
109→        );
110→      })}
111→    </div>
112→  );
113→}
