135→        {prev ? (
136→          <Link href={`/work/${prev.slug}`} className="hover-dim" style={{ fontSize: 16, color: "var(--text)" }}>
137→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Previous</span>
138→            {prev.title}
139→          </Link>
140→        ) : <div />}
141→        {next ? (
142→          <Link href={`/work/${next.slug}`} className="hover-dim" style={{ fontSize: 16, color: "var(--text)", textAlign: "right" }}>
143→            <span style={{ fontSize: 11, color: "var(--muted)", letterSpacing: "0.08em", textTransform: "uppercase", display: "block", marginBottom: 4 }}>Next</span>
144→            {next.title}
145→          </Link>
146→        ) : <div />}
147→      </div>
148→
149→      <div style={{ height: 60 }} />
150→    </div>
151→  );
152→}
